"""Stage 06 message contract. A GID is deterministic and generated by the server."""
from __future__ import annotations
from typing import Literal
from uuid import UUID
from pydantic import BaseModel, Field

class PrepareMessage(BaseModel):
    tx_id: UUID
    shard_id: Literal['A','B','C']
    role: Literal['DEBIT','CREDIT']
    account_id: str = Field(pattern=r'^A[0-9]{4}$')
    amount: str
    epoch: int = Field(ge=1)

class DecisionMessage(BaseModel):
    tx_id: UUID
    shard_id: Literal['A','B','C']
    decision: Literal['COMMIT','ABORT']


def gid_for(tx_id: UUID | str, shard: str) -> str:
    if shard not in ('A','B','C'):
        raise ValueError('invalid participant shard')
    return f'bank2pc:{UUID(str(tx_id))}:{shard}'
